// Combo blast: clear bricks in area below the ball at combo milestones
function comboBlast(fx,fy){
  let radius=combo>=50?200:combo>=30?160:combo>=20?120:100;
  let blastColor=combo>=50?'#f00':combo>=30?'#f80':combo>=20?'#ff0':'#0ff';
  addFloatText(fx,fy-30,'COMBO BLAST! '+combo+'x',blastColor,28);
  triggerShake(8,20);sfxExplosion();
  // Visual ring
  for(let i=0;i<40;i++){
    let angle=Math.random()*Math.PI*2;
    let dist=Math.random()*radius;
    spawnParticles(fx+Math.cos(angle)*dist,fy+Math.sin(angle)*dist,blastColor,2);
  }
  // Destroy bricks below ball within radius
  for(let b of bricks){
    if(!b.alive)continue;
    let cx=b.x+b.w/2,cy=b.y+b.h/2;
    // Only clear bricks below the blast origin
    if(cy>=fy&&Math.abs(cx-fx)<radius&&cy-fy<radius){
      b.alive=false;score+=50*scoreMult;
      spawnParticles(cx,cy,blastColor,8);
      addFloatText(cx,cy,'+'+50*scoreMult,blastColor,12);
    }
  }
  document.getElementById('scoreVal').textContent=score;
}

